 void Fullscreen(bool on){settings.Fullscreen=on;if(on){windowBounds=Bounds;FormBorderStyle=FormBorderStyle.None;WindowState=FormWindowState.Normal;Bounds=Screen.FromControl(this).Bounds;}else {FormBorderStyle=FormBorderStyle.Sizable;WindowState=FormWindowState.Normal;if(windowBounds.Width>0)Bounds=windowBounds;else ClientSize=new Size(1100,800);}Save();}
 void KeyPressed(object sender,KeyEventArgs e){bool fresh=keys.Add(e.KeyCode);if(!fresh)return;if(e.KeyCode==Keys.M){settings.Muted=!settings.Muted;ApplyAudio();Save();soundNotice=2;return;}if(page=="settings"&&(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right)&&selected<buttons.Count&&buttons[selected].SetValue!=null){ButtonArea slider=buttons[selected];slider.SetValue(Math.Max(0,Math.Min(1,slider.GetValue()+(e.KeyCode==Keys.Right?.05f:-.05f))));ApplyAudio();Save();return;}if(page=="upgrade"){if(e.KeyCode==Keys.Left)selected=(selected+2)%3;if(e.KeyCode==Keys.Right)selected=(selected+1)%3;if(e.KeyCode>=Keys.D1&&e.KeyCode<=Keys.D3){AcceptPath((int)e.KeyCode-(int)Keys.D1);return;}}if(e.KeyCode==Keys.F11){Fullscreen(!settings.Fullscreen);return;}if(e.KeyCode==Keys.Escape){mouseSteering=false;if(page=="game")page="pause";else if(page=="pause")page="game";else if(page=="flightsettings")page="settings";else if(page=="settings"||page=="controls")page=back;else if(page=="levels")page="menu";selected=0;firing=false;return;}if(page=="game"){if(e.KeyCode==Keys.W||e.KeyCode==Keys.A||e.KeyCode==Keys.S||e.KeyCode==Keys.D||e.KeyCode==Keys.Up||e.KeyCode==Keys.Down||e.KeyCode==Keys.Left||e.KeyCode==Keys.Right)mouseSteering=false;if(e.KeyCode==Keys.Space)boost=true;return;}if(e.KeyCode==Keys.Down||e.KeyCode==Keys.S)selected=(selected+1)%Math.Max(1,buttons.Count);if(e.KeyCode==Keys.Up||e.KeyCode==Keys.W)selected=(selected+Math.Max(1,buttons.Count)-1)%Math.Max(1,buttons.Count);if(e.KeyCode==Keys.Enter&&buttons.Count>0){Action a=buttons[Math.Min(selected,buttons.Count-1)].Action;a();selected=0;}Invalidate();}
 void MousePressed(object sender,MouseEventArgs e){mouse=Map(e.Location);if(page=="game"){if(e.Button==MouseButtons.Left)firing=true;if(e.Button==MouseButtons.Right)bomb=true;if(e.Button==MouseButtons.Middle)boost=true;}else if(e.Button==MouseButtons.Left){foreach(ButtonArea b in buttons)if(b.R.Contains(mouse.X,mouse.Y)){if(b.SetValue!=null){activeSlider=b;Capture=true;SlideToPointer(b);}else{b.Action();selected=0;}break;}}}
 bool Held(Keys a,Keys b){return keys.Contains(a)||keys.Contains(b);}
 void MouseMoved(object sender,MouseEventArgs e){mouse=Map(e.Location);if(activeSlider!=null)SlideToPointer(activeSlider);if(page=="game")mouseSteering=viewport.Contains(e.Location);}
 void PlayerStep(float dt,V keyboard){
  V move=keyboard,aim=mouse;float speed=290;
  if(settings.MouseFlight){
   // In mouse flight the rocket and its guns face upward, independently of steering.
   aim=new V(world.Player.X,-100000);
   if(keyboard.Length==0&&mouseSteering){speed=FlightControls.MouseSpeed;bool fast=world.BoostTime>dt||(boost&&world.BoostCD<=dt);move=FlightControls.Follow(world.Player,mouse,dt,fast?900:speed*world.FlightScale);}
  }
  world.Step(dt,move,aim,firing||settings.AutoFire,boost,speed,settings.MouseFlight);
 }
 protected override bool IsInputKey(Keys keyData){Keys k=keyData&Keys.KeyCode;if(k==Keys.Left||k==Keys.Right||k==Keys.Up||k==Keys.Down)return true;return base.IsInputKey(keyData);}
 void Tick(object sender,EventArgs e){float now=(float)clock.Elapsed.TotalSeconds,dt=Math.Min(.05f,now-last);last=now;total+=dt;soundNotice=Math.Max(0,soundNotice-dt);ApplyAudio();audio.Pump();
  if(page=="game"){
   V move=new V((Held(Keys.D,Keys.Right)?1:0)-(Held(Keys.A,Keys.Left)?1:0),(Held(Keys.S,Keys.Down)?1:0)-(Held(Keys.W,Keys.Up)?1:0));
   if(auto){for(int i=0;i<12;i++){Pilot(1f/60);autoTime+=1f/60;}if(world.Won||world.Lost)Finish();}
   else if(benchmark){Pilot(dt);autoTime+=dt;}
   else{PlayerStep(dt,move);if(bomb&&world.PendingTier==0)world.Bomb();boost=bomb=false;if(world.Won||world.Lost)Finish();else if(world.PendingTier>0){page="upgrade";selected=0;firing=false;mouseSteering=false;keys.Clear();}}
   if(world.Level+1>settings.Unlocked){settings.Unlocked=world.Level+1;Save();}
  }
  if(auto&&world.Level==3&&world.Time>20&&!File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"campaign.png")))CaptureFrame("campaign");
  if(auto&&world.PendingBoss){Entity visibleBoss=world.Entities.Find(delegate(Entity candidate){return candidate.Kind=="boss";});if(visibleBoss!=null&&visibleBoss.Age>5&&!File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"final-encounter.png")))CaptureFrame("final-encounter");}
  if(auto&&page=="victory"){CaptureFrame("victory");if(report!=null)File.WriteAllText(report,"Packaged rendered autopilot campaign: VICTORY\nSimulated seconds: "+autoTime+"\nRendered frames: "+rendered+"\nMean draw milliseconds: "+(renderMs/Math.Max(1,rendered)).ToString("F2")+"\nShots: "+world.Shots+" Kills: "+world.Kills+" Pickups: "+world.Pickups+" Damage events: "+world.DamageEvents+"\nHull: "+world.PlayerName+" / Mini-bosses: "+world.MiniDefeated+" / Drones: "+world.DroneCount+" / Interceptions: "+world.DroneBlocks+" / Missiles: "+world.MissilesLaunched+"\nAudio device: "+audio.Available+"\nQA pilot auto-repair enabled; not an unaided difficulty test.");auto=false;if(report!=null){Close();return;}}
  if(benchmark&&clock.Elapsed.TotalSeconds>=32){frameTimes.Sort();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"benchmark-results.txt"),"Live native-window sector 4 benchmark, 32 seconds, "+ClientSize.Width+"x"+ClientSize.Height+"\nPresented paint rate: "+(rendered/clock.Elapsed.TotalSeconds).ToString("F1")+" FPS\nMean drawing: "+(renderMs/Math.Max(1,rendered)).ToString("F2")+" ms\nVirtual draw: "+(virtualMs/Math.Max(1,rendered)).ToString("F2")+" ms; scaling: "+(scaleMs/Math.Max(1,rendered)).ToString("F2")+" ms\n95th percentile drawing: "+frameTimes[(int)(frameTimes.Count*.95)].ToString("F2")+" ms\nAudio output: "+audio.Available+"\n"+Environment.GetEnvironmentVariable("PROCESSOR_IDENTIFIER"));Close();return;}
  if(qa){qaClock+=dt;if(qaClock>.4f){qaClock=0;QATick();}}
  Invalidate();
 }
 void Pilot(float dt){if(world.PendingTier>0)world.ChooseUpgrade(world.Level%3);Entity target=null;float best=float.MaxValue;foreach(Entity e in world.Entities){if(world.Targetable(e)){float d=(e.P-world.Player).Length;if(d<best&&e.P.Y>0){best=d;target=e;}}}V aim=target==null?new V(480,0):target.P;Entity pickup=world.Entities.Find(delegate(Entity e){return e.Kind=="upgrade"||e.Kind=="drone";})??world.Entities.Find(delegate(Entity e){return e.Kind=="pickup";});V goal=pickup!=null?pickup.P:new V(480+(float)Math.Sin(autoTime*.4)*280,660);V move=(goal-world.Player);if(move.Length>6)move=move.Unit;else move=new V();world.Step(dt,move,aim,true,false);
  // QA pilot uses explicit replenishment; it is a soak test, not a difficulty claim.
  if(world.Health<35)world.Health=100;
  if(world.Bombs>0&&world.Entities.Count>22)world.Bomb();
 }
