  else if(page=="victory"||page=="over"){bool won=page=="victory";Title(g,won?"THE SIGNAL IS SAFE":"ROCKET LOST",won?"MISSION COMPLETE":"GAME OVER");art.Text(g,"SCORE  "+world.Score.ToString("N0")+"     /     SECTOR 0"+(world.Level+1),480,239,23,Art.Gold,true);art.Text(g,won?"The dreadnought is silent. The frontier is yours.":"A new rocket is ready. Take another run.",480,292,21,Color.LightSteelBlue,true);Button(g,won?"PLAY AGAIN":"RETRY SECTOR",385,delegate{Start(won?0:world.Level,won?0:world.Tier,won?-1:world.Branch,won?0:world.DroneCount,won?settings.Difficulty:world.Difficulty);});Button(g,"MAIN MENU",449,delegate{page="menu";back="menu";});Button(g,"EXIT",513,delegate{Close();});}
  art.Text(g,"UP / DOWN + ENTER or mouse to navigate",480,746,14,Color.SlateGray,true);
 }
 static float Cycle(float v){int n=(int)Math.Round(v*4);return n>=4?0:(n+1)*.25f;}
 void AssertQA(bool condition,string text){if(!condition)throw new Exception("UI QA: "+text);qaResults.Add("PASS: "+text);}
 void CaptureFrame(string name){using(Bitmap bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name+".png"));}}
 // Application-level tests invoke the same input handlers as Windows events.
 void QATick(){switch(qaStage++){
  case 0: AssertQA(page=="menu"&&buttons.Count==5,"main menu renders five actions");AssertQA(IsInputKey(Keys.Left)&&IsInputKey(Keys.Right)&&IsInputKey(Keys.Up)&&IsInputKey(Keys.Down),"arrow keys routed to game input");CaptureFrame("menu");KeyPressed(this,new KeyEventArgs(Keys.Enter));keys.Clear();AssertQA(page=="game","Enter activates Play");world.Transition=0;baselineX=world.Player.X;KeyPressed(this,new KeyEventArgs(Keys.D));break;
  case 1: AssertQA(world.Player.X>baselineX+20,"held movement event moves rocket");keys.Clear();mouse=new V(480,130);firing=true;break;
  case 2: AssertQA(world.Shots>0&&world.Ammo<180,"held left fire and mouse aim");firing=false;KeyPressed(this,new KeyEventArgs(Keys.Space));break;
  case 3: AssertQA(world.BoostCD>0,"Space boost event");keys.Clear();MousePressed(this,new MouseEventArgs(MouseButtons.Right,1,ClientSize.Width/2,ClientSize.Height/2,0));break;
  case 4: AssertQA(world.Bombs==2,"right-button bomb action");KeyPressed(this,new KeyEventArgs(Keys.Escape));keys.Clear();baselineX=world.Time;break;
  case 5: AssertQA(page=="pause"&&world.Time==baselineX,"Esc pauses simulation");CaptureFrame("pause");KeyPressed(this,new KeyEventArgs(Keys.Escape));keys.Clear();AssertQA(page=="game","Esc resumes");Entity e=world.Add("crate",world.Player,1,23);e.Type=1;world.Health=50;break;
  case 6: AssertQA(world.Pickups>0&&world.Health>=80,"contact crate and health collection");world.Invulnerable=0;world.Damage(20);AssertQA(world.Invulnerable>0&&world.Health<=80,"damage feedback and protection");CaptureFrame("gameplay");world.Invulnerable=0;world.Damage(200);break;
  case 7: AssertQA(page=="over","game-over screen");CaptureFrame("game-over");KeyPressed(this,new KeyEventArgs(Keys.Enter));keys.Clear();AssertQA(page=="game"&&!world.Lost&&world.Health==100,"retry action resets rocket");world.Transition=0;world.Time=48;world.Entities.Clear();world.SpawnClock=999;break;
  case 8: AssertQA(world.Level==1&&world.Transition>0,"level transition in live loop");KeyPressed(this,new KeyEventArgs(Keys.Escape));keys.Clear();break;
  case 9: selected=1;KeyPressed(this,new KeyEventArgs(Keys.Enter));keys.Clear();AssertQA(page=="settings","pause Settings action");break;
  case 10: float old=settings.Music;selected=2;KeyPressed(this,new KeyEventArgs(Keys.Enter));keys.Clear();AssertQA(Settings.Load(settingsPath).Music==settings.Music&&settings.Music!=old,"volume changes persist");settings.Music=old;Save();CaptureFrame("settings");page="controls";break;
  case 11: CaptureFrame("controls");AssertQA(buttons.Count==1,"help screen renders");Fullscreen(true);AssertQA(FormBorderStyle==FormBorderStyle.None&&Bounds==Screen.FromControl(this).Bounds,"fullscreen window bounds");Fullscreen(false);ClientSize=new Size(900,760);AssertQA(FormBorderStyle==FormBorderStyle.Sizable,"windowed restore and resize");page="game";world=new World(4,4);world.Sound=audio.Play;world.Transition=0;world.Time=48;break;
  case 12: Entity boss=world.Entities.Find(delegate(Entity v){return v.Kind=="boss";});AssertQA(boss!=null,"boss appears in live loop");boss.P=new V(480,190);CaptureFrame("boss");world.Destroy(boss);break;
  case 13: AssertQA(page=="victory","victory screen");CaptureFrame("victory");settings.Difficulty=0;selected=0;KeyPressed(this,new KeyEventArgs(Keys.Enter));keys.Clear();AssertQA(world.Difficulty==0,"play again applies next-run difficulty");settings.Difficulty=1;settings.MouseFlight=true;Start(0);world.Transition=0;world.SpawnClock=999;world.SupplyClock=999;MoveTestPointer(new V(650,550));break;
  case 14: AssertQA(world.Player.X>500&&world.Player.Y<640,"mouse movement steers rocket");firing=true;break;
  case 15: AssertQA(world.Entities.Exists(delegate(Entity v){return v.Kind=="bullet"&&v.Vel.X==0&&v.Vel.Y<0;}),"mouse flight fires upward while steering");firing=false;MoveTestPointer(world.Player);MousePressed(this,new MouseEventArgs(MouseButtons.Middle,1,(int)(viewport.X+mouse.X*viewport.Width/960),(int)(viewport.Y+mouse.Y*viewport.Height/780),0));break;
  case 16: AssertQA(world.BoostCD>0,"middle mouse triggers boost");KeyPressed(this,new KeyEventArgs(Keys.Escape));keys.Clear();MoveTestPointer(new V(200,200));baselineX=world.Player.X;break;
  case 17: AssertQA(page=="pause"&&world.Player.X==baselineX&&!mouseSteering,"paused pointer cannot steer rocket");KeyPressed(this,new KeyEventArgs(Keys.Escape));keys.Clear();baselineX=world.Player.X;break;
  case 18: AssertQA(world.Player.X==baselineX,"resume waits for new mouse movement");KeyPressed(this,new KeyEventArgs(Keys.Escape));keys.Clear();page="settings";back="pause";break;
  case 19: selected=4;KeyPressed(this,new KeyEventArgs(Keys.Enter));keys.Clear();buttons.Clear();using(Graphics testGraphics=Graphics.FromImage(canvas))DrawFleetMenus(testGraphics);selected=1;KeyPressed(this,new KeyEventArgs(Keys.Enter));keys.Clear();page="settings";AssertQA(!settings.MouseFlight&&!Settings.Load(settingsPath).MouseFlight,"settings switches and saves keyboard mode");settings.MouseFlight=true;Save();CaptureFrame("mouse-flight-settings");KeyPressed(this,new KeyEventArgs(Keys.M));keys.Clear();break;
  case 20: AssertQA(settings.Muted&&audio.Music==0&&audio.Effects==0&&Settings.Load(settingsPath).Muted,"M mutes both channels and persists");KeyPressed(this,new KeyEventArgs(Keys.M));keys.Clear();AssertQA(!settings.Muted&&audio.Music==settings.MusicGain,"M unmutes with volume restored");MoveTestPointer(new V(480,250));MousePressed(this,new MouseEventArgs(MouseButtons.Left,1,(int)(viewport.X+480*viewport.Width/960),(int)(viewport.Y+250*viewport.Height/780),0));MoveTestPointer(new V(562,250));activeSlider=null;Capture=false;break;
  case 21: AssertQA(Math.Abs(settings.Master-.75f)<.015f&&Math.Abs(Settings.Load(settingsPath).Master-settings.Master)<.0001f,"master volume drag saves and applies");CaptureFrame("evolution-settings");Start(0);world.Transition=0;world.SpawnClock=999;world.SupplyClock=999;world.Score=1500;break;
  case 22: Entity core=world.Entities.Find(delegate(Entity v){return v.Kind=="upgrade";});AssertQA(core!=null&&world.Tier==0,"live milestone drops optional gold core");core.P=world.Player;break;
  case 23: AssertQA(page=="upgrade"&&world.PendingTier==1,"upgrade pauses action for ship choice");CaptureFrame("branch-choice");AcceptPath(0);AssertQA(world.Tier==1,"live collection evolves ship");world.Score=5000;world.UpgradeClock=0;world.OfferUpgrade(.1f);core=world.Entities.Find(delegate(Entity v){return v.Kind=="upgrade"&&!v.Dead;});core.P=world.Player;break;
  case 24: AcceptPath(1);AssertQA(world.Tier==2,"second live transformation");world.Score=11000;world.UpgradeClock=0;world.OfferUpgrade(.1f);core=world.Entities.Find(delegate(Entity v){return v.Kind=="upgrade"&&!v.Dead;});core.P=world.Player;break;
  case 25: AcceptPath(2);AssertQA(world.Tier==3,"Dreadstar live transformation");CaptureFrame("evolved-player");int earned=world.Tier;Start(world.Level,world.Tier,world.Branch,world.DroneCount,world.Difficulty);AssertQA(world.Tier==earned,"sector retry retains earned hull");page="game";world.Transition=0;world.SpawnClock=999;world.SupplyClock=999;break;
 default: FleetQaStep(qaStage-1);break;
 }}
 void MoveTestPointer(V p){MouseMoved(this,new MouseEventArgs(MouseButtons.None,0,(int)(viewport.X+p.X*viewport.Width/960),(int)(viewport.Y+p.Y*viewport.Height/780),0));}
}
